Подивись на цей фрагмент з нового PR у server і скажи, що не так з точки зору архітектури та як виправити:

```ts
// server/src/modules/digest/routes.ts
import { eq, desc } from 'drizzle-orm';
import * as t from '../../db/schema.js';
import { OctokitGitHubClient } from '../../adapters/github/octokit.js';
import { toAgentDto } from '../agents/helpers.js';

export default async function digestRoutes(app: FastifyInstance) {
  app.get('/repos/:id/digest', async (req, reply) => {
    const id = (req.params as any).id;
    const gh = new OctokitGitHubClient(process.env.GITHUB_TOKEN!);
    const reviews = await app.container.db.select().from(t.reviews).where(eq(t.reviews.repoId, id)).orderBy(desc(t.reviews.createdAt));
    const critical = reviews.filter(r => r.score < 50);
    if (critical.length > 3) reply.status(409);
    return { critical, agents: (await app.container.agentsRepo.list(id)).map(toAgentDto) };
  });
}
